            "patterns": [
              {
                "group": [
                  "fetch"
                ],
                "message": "Use the request util from ~/common/utils/request instead of importing fetch directly"
              },
              {
                "group": [
                  "../*",
                  "../**"
                ],
                "message": "Within src/ingestion, import via the ~/ alias instead of parent-relative (../) paths."
              },
              {
                "group": [
                  "~/cdp",
                  "~/cdp/**"
                ],
                "message": "ingestion never reaches cdp (nodejs/src/ingestion/Ingestion.spec.md): do not import ~/cdp from ingestion; depend on the contracts in ~/common."
              }
            ],
            "paths": [
              {
                "name": "node-fetch",
                "message": "Use the request util from ~/common/utils/request instead of node-fetch"
              },
              {
                "name": "undici",
                "message": "Use the request util from ~/common/utils/request instead of undici"
              }
            ]
          }
        ]
